SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- maozi-cloud-nacos-middleware-db 可以改成自己的库名
DROP DATABASE IF EXISTS `maozi-cloud-nacos-middleware-db`;
CREATE DATABASE `maozi-cloud-nacos-middleware-db` CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `maozi-cloud-nacos-middleware-db`;
-- maozi-cloud-nacos-middleware-db 可以改成自己的库名

-- ----------------------------
-- Table structure for config_info
-- ----------------------------
DROP TABLE IF EXISTS `config_info`;
CREATE TABLE `config_info` (
                               `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
                               `data_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8_bin NOT NULL COMMENT 'data_id',
                               `group_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT NULL,
                               `content` longtext CHARACTER SET utf8mb3 COLLATE utf8_bin NOT NULL COMMENT 'content',
                               `md5` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT NULL COMMENT 'md5',
                               `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                               `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
                               `src_user` text CHARACTER SET utf8mb3 COLLATE utf8_bin COMMENT 'source user',
                               `src_ip` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT NULL COMMENT 'source ip',
                               `app_name` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT NULL,
                               `tenant_id` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT '' COMMENT '租户字段',
                               `c_desc` varchar(256) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT NULL,
                               `c_use` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT NULL,
                               `effect` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT NULL,
                               `type` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT NULL,
                               `c_schema` text CHARACTER SET utf8mb3 COLLATE utf8_bin,
                               `encrypted_data_key` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '密钥',
                               PRIMARY KEY (`id`) USING BTREE,
                               UNIQUE KEY `uk_configinfo_datagrouptenant` (`data_id`,`group_id`,`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=8537 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='config_info';

-- ----------------------------
-- Records of config_info
-- ----------------------------
BEGIN;
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (3287, 'a.yml', 'DEFAULT_GROUP', 'a=abc', '1c8128107bd726f312947b043e28572a', '2026-02-28 07:44:31', '2026-02-28 07:45:11', 'nacos', '172.18.0.1', '', '75bc1675-1e8e-4099-b2f2-d9482ce14f4e', '', '', '', 'properties', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5550, 'boot-datasource.yml', 'DEFAULT_GROUP', 'spring:\n  datasource:\n    # 连接池实现类，HikariCP 是 Spring Boot 2.x 起的默认连接池，主打轻量高性能\n    type: com.zaxxer.hikari.HikariDataSource\n    # MySQL 8.x 驱动（Connector/J 8+ 类名带 cj，5.x 是 com.mysql.jdbc.Driver）\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    # JDBC 连接串，主机/库名支持占位符覆盖，不覆盖时取默认值：\n    #   主机端口 -> ${application-datasource-jdbc-url}，默认容器内基础 MySQL 服务\n    #   库名 -> ${application-datasource-db-name}，默认「应用名-环境-db」，每个服务独立库\n    # 连接参数：\n    #   useSSL=false             内网直连关闭 SSL，避免自签证书告警\n    #   serverTimezone=Asia/Shanghai  指定时区，不配可能报时区无法识别或时间偏差8小时\n    #   characterEncoding=utf8   字符编码\n    #   nullCatalogMeansCurrent=true  元数据查询只查当前库；MySQL 8 驱动默认 false 会扫出所有库，影响代码生成器/Flyway 等按 catalog 查表的场景\n    url: jdbc:mysql://${application-datasource-jdbc-url:maozi-cloud-basic-mysql:3306}/${application-datasource-db-name:${spring.application.name}-${application.environment}-db}?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8&nullCatalogMeansCurrent=true\n    # 账号密码，生产环境通过配置中心/环境变量覆盖，这里仅本地默认值\n    username: ${application-datasource-jdbc-username:root}\n    password: ${application-datasource-jdbc-password:password}\n    # Hikari 连接池参数\n    hikari:\n      # 最大连接，根据业务压测调整，默认推荐10~20，不要直接50\n      maximum-pool-size: 15\n      # 获取连接等待超时时间（6s），池耗尽时最多等这么久，超时抛异常快速失败，避免请求线程被长时间挂起\n      connection-timeout: 6000\n      # 不配置minimum-idle，Hikari官方推荐，最小空闲连接等于最大连接（固定大小池，避免频繁建连）\n      # minimum-idle: 10\n      # 空闲连接超时（5min），注意必须小于max-lifetime\n      idle-timeout: 300000\n      # 连接最大存活时间（540s=9min），比mysql wait_timeout小至少60s，到期连接异步关闭重建，避免拿到已被服务端断开的连接\n      max-lifetime: 540000\n      # 删掉 connection-test-query，Hikari用JDBC4 isValid校验', '68b1e0da70513fae5ff90b2fef4e8ef6', '2026-07-03 13:54:34', '2026-10-21 14:00:36', NULL, '172.18.0.1', '', 'local', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5551, 'boot-elasticsearch.yml', 'DEFAULT_GROUP', '# Elasticsearch 连接配置（当前未接入 ES，接入时调整地址后由对应 starter 加载）\nspring:\n  data:\n    elasticsearch:\n    ####集群名称\n     cluster-name: maozi-cloud-es\n    ####地址 \n     cluster-nodes: 192.168.0.1,192.168.0.2', 'b7f02bc256acdd0743ff8c965b8e9f1d', '2026-07-03 13:54:34', '2026-10-21 14:19:47', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5553, 'boot-redis.yml', 'DEFAULT_GROUP', '# Redis 连接配置：地址/密码均可通过环境变量覆盖，默认指向容器内基础 Redis\nspring:\n  data:\n    redis:\n      # Redis 地址（本地直连时用环境变量 APPLICATION_REDIS_SERVER=127.0.0.1 覆盖）\n      host: ${APPLICATION_REDIS_SERVER:maozi-cloud-basic-redis}\n      port: ${APPLICATION_REDIS_PORT:6379}\n      # 密码从环境变量读取，禁止硬编码\n      password: ${APPLICATION_REDIS_SERVER_PASSWORD:password}\n      # 逻辑库编号（0~15），按环境/业务做数据隔离\n      database: ${APPLICATION_REDIS_SERVER_DATABASE:0}\n      # 可选，客户端标识，方便redis client list排查\n      client-name: ${spring.application.name}-${application.environment}-${application.version}\n      lettuce:\n        # 命令超时，建议500ms，根据业务微调，不要超过1s\n        timeout: 500ms\n        shutdown-timeout: 300ms\n        pool:\n          # 最大活跃连接，根据单实例QPS，一般80~200\n          max-active: 120\n          # 获取连接最大等待时间1s\n          max-wait: 1000ms\n          max-idle: 60\n          # 维持少量预热连接\n          min-idle: 10', '09b93eeca64b2d1aa16848a2221aa0b7', '2026-07-03 13:54:34', '2026-10-21 16:09:57', NULL, '172.18.0.1', '', 'local', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5575, 'cloud-default.yml', 'DEFAULT_GROUP', '# 所有服务共用的兜底配置：Web容器、优雅停机、序列化、Feign、日志级别（服务自身 yml 可覆盖）\nserver:\n  port: ${APPLICATION_PORT:${application.port:0}}\n  # 出错/找不到处理器时的统一转发路径\n  error.path: /application/error\n  # graceful=优雅停机 / immediate=立刻关闭\n  shutdown: graceful\n  undertow:\n    # 单个请求超时时间，单位毫秒\n    request-timeout: 30000\n  # compression:\n  #   enabled: true\n  #   min-response-size: 1024\n  #   mime-types: application/json,application/xml,text/html,text/xml,text/plain\n\nspring:\n  lifecycle:\n    # 优雅停机等待最大超时时间，按需调整，一般10~30s\n    timeout-per-shutdown-phase: 65s\n  main:\n    # 关闭 banner 与启动日志，保持控制台干净\n    banner-mode: off\n    log-startup-info: false\n  web:\n    resources:\n      # 不映射静态资源，纯接口服务\n      add-mappings: false\n  mvc: \n    # 404 抛 NoHandlerFoundException，交给全局异常处理器\n    throw-exception-if-no-handler-found: true\n    # ANT 路径匹配策略，兼容文档工具的老写法\n    pathmatch.matching-strategy: ant_path_matcher\n  # 全局 JSON 序列化：时区/日期格式统一，null 字段不输出\n  jackson: \n    time-zone: GMT+8\n    date-format: yyyy-MM-dd HH:mm:ss\n    default-property-inclusion: NON_NULL\n\n# OpenFeign 远程调用\nfeign:\n  sentinel:\n    enabled: true\n  # 底层 HTTP 客户端用 OkHttp（优于默认实现），禁用 HttpClient\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  # 默认超时 30s，按下游实际耗时调整\n  client:\n    config:\n      default:\n        connectTimeout: 30000\n        readTimeout: 30000\n  compression:\n    request:\n      # 开启请求数据的压缩功能\n      enabled: true\n      # 最小压缩值标准，当数据大于 1024 才会进行压缩\n      min-request-size: 1024\n      # 压缩类型\n      mime-types: text/xml,application/xml,application/json\n    response:\n      enabled: true\n\n# 日志级别：根 ERROR、业务包 INFO、Dubbo 注册/通信日志关闭\nlogging: \n  level: \n    root: ERROR\n    com.maozi: INFO\n    org.apache.dubbo.registry: OFF\n    org.apache.dubbo.remoting: OFF', '54091f124116f7232eeb3cdc06e6f5e2', '2026-07-03 13:54:34', '2026-10-21 14:19:47', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5576, 'cloud-dubbo.yml', 'DEFAULT_GROUP', '# Dubbo RPC 配置：应用、扫描、协议、超时、注册中心\ndubbo:\n  application: \n    name: dubbo-${spring.application.name}\n    # instance/interface/all\n    register-mode: instance\n    # 应用版本（随 application.version），用于版本路由/灰度\n    version: ${application.version:main}\n    # 内网环境关闭序列化安全检查，避免自定义实体校验报错\n    serialize-check-status: DISABLE\n    check-serializable: false\n  # RPC 实现类扫描包，按项目缩写拼接（如 system → com.maozi.system.*.api.impl.rpc）\n  scan:\n    base-packages: com.maozi.${application-project-abbreviation}.*.api.impl.rpc\n  # 通信协议：dubbo；需要 Triple/gRPC 协议时放开上面 tri 注释\n  protocol:\n    # name: tri\n    name: dubbo\n    # Dubbo 端口，-1=随机；固定端口用 APPLICATION_DUBBO_PORT / application.dubbo.port 指定\n    port: ${APPLICATION_DUBBO_PORT:${application.dubbo.port:-1}}\n  provider:\n    # 提供方默认超时 6s，本地快速失败便于定位问题\n    timeout: 6000\n    # 自定义过滤器：服务端还原用户/链路上下文\n    filter: applicationDubboContextLoadFilter\n    # 序列化统一 hessian2，避免多协议协商问题\n    prefer-serialization: hessian2\n    serialization: hessian2\n  consumer:\n    # 启动不检查依赖方是否在线，解除服务启动顺序耦合\n    check: false\n    # 消费方默认超时 6s\n    timeout: 6000\n    # 失败自动重试 1 次，非幂等接口记得在 @DubboReference 上单独关闭\n    retries: 1\n    # 自定义过滤器：消费端透传用户/链路上下文\n    filter: applicationDubboContextTransmitFilter\n  # 注册中心复用 Nacos（与配置中心同实例），namespace 随环境隔离\n  registry:\n    address: nacos://${spring.cloud.nacos.discovery.server-addr}?namespace=${spring.cloud.nacos.discovery.namespace}', '4a6a4e5a896295cd27a7a9049b4e7397', '2026-07-03 13:54:34', '2026-10-21 14:19:47', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5577, 'cloud-nacos.yml', 'DEFAULT_GROUP', '# Nacos 服务发现配置\nspring: \n  cloud: \n    nacos: \n      discovery:\n        enabled: true\n        register-enabled: true\n        # 实例元数据带版本号，灰度路由按此筛选实例\n        metadata: \n          version: ${application.version:main}', '111d89ef9c371c69bba00d1c1671f74c', '2026-07-03 13:54:34', '2026-10-21 14:19:47', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5578, 'cloud-rocket.yml', 'DEFAULT_GROUP', '# RocketMQ 配置（当前未启用，接入 MQ 时改 name-server 并由对应 starter 加载）\nspring:\n  cloud:\n    stream:\n      rocketmq:\n        binder:\n          # access-key: \n          # secret-key: \n          name-server: localhost:9876\n# rocketmq:\n  # instance:\n    # id: \n    # name: ', '79542009b0f9f0671e3dc245bbf7022b', '2026-07-03 13:54:34', '2026-10-21 14:19:47', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5579, 'cloud-sentinel.yml', 'DEFAULT_GROUP', '# RestTemplate 请求也纳入 Sentinel 保护\nresttemplate:\n  sentinel:\n    enabled: true\n\nfeign:\n  # Feign 接口接入 Sentinel 熔断降级\n  sentinel: \n    enabled: true\n\n# Sentinel 客户端：控制台接入 + 规则持久化到 Nacos\nspring: \n  cloud: \n    sentinel:\n      # 规则数据源前缀：应用名-环境-版本（规则统一存 middleware 命名空间 SENTINEL_GROUP）\n      name: ${spring.application.name}-${application.environment:local}-${application.version:main}\n      # 启动即注册到控制台，不等首次请求\n      eager: true\n      transport:\n        # 与控制台通信的本地端口，被占用会自动顺延\n        port: 8719\n        # Sentinel 控制台地址\n        dashboard: ${APPLICATION_SENTINEL_SERVER:maozi-cloud-basic-sentinel:8858}\n      # 资源名带 HTTP 方法（如 GET:/user/info），避免同路径不同方法混淆\n      http-method-specify: true\n      # 规则持久化：控制台改动写回 Nacos，客户端监听变更实时生效\n      datasource:\n        # 流控规则\n        flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-flow-rules.json\n            rule-type: flow\n        # 熔断降级规则\n        degrade:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-degrade-rules.json\n            rule-type: degrade\n        # 热点参数限流规则\n        param-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-param-rules.json\n            rule-type: param-flow\n        # 系统自适应保护规则\n        system:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-system-rules.json\n            rule-type: system\n        # 黑白名单授权规则\n        authority:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            data-id: ${spring.cloud.sentinel.name}-authority-rules.json\n            rule-type: authority', '84ec3b202774d7cf612226b52eaadeb3', '2026-07-03 13:54:34', '2026-10-21 14:19:47', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5642, 'boot-arthas.yml', 'DEFAULT_GROUP', '# Arthas 在线诊断：通过 Tunnel Server 远程连接排查问题\narthas: \n  # 在 Tunnel 面板里的唯一标识，用应用名方便定位\n  agent-id: ${spring.application.name}\n  # Tunnel Server 地址（本地 7777，容器环境替换为 tunnel 服务地址）\n  tunnel-server: ws://localhost:7777/ws\n  # -1=不开启本地 telnet/http 端口，只走 Tunnel\n  telnet-port: -1\n  http-port: -1', '8e12074f821ddc3b85a0de0fb2e2990a', '2026-07-03 13:54:34', '2026-10-21 14:19:47', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5643, 'boot-lock.yml', 'DEFAULT_GROUP', '# Redisson 分布式锁：复用 Redis 连接配置\nlock:\n  redisson:\n    # 锁实例与 spring.data.redis 同源，改 Redis 配置时这里自动跟随\n    address: redis://${spring.data.redis.host}:${spring.data.redis.port}\n    password: ${spring.data.redis.password}\n    database: ${spring.data.redis.database:0}\n    # waitTime: 60 #获取锁最长阻塞时间（默认：60，单位：秒）\n    # leaseTime: 60 #已获取锁后自动释放时间（默认：60，单位：秒）\n    # redis集群配置 如 redis://127.0.0.1:7000,redis://127.0.0.1:7001,redis://127.0.0.1:7002\n    # spring.klock.address 和 spring.klock.cluster-server.node-addresses 选其一即可\n    # cluster-server.node-addresses:', '31e5dee8e68b08adceb533597727ddeb', '2026-07-03 13:54:34', '2026-10-21 14:19:47', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5644, 'boot-monitor.yml', 'DEFAULT_GROUP', '# 监控客户端：注册到 Spring Boot Admin + Actuator 端点暴露\nspring:  \n  boot: \n    admin: \n      client:\n        # SBA 服务端地址，启动后自动注册\n        url: http://${APPLICATION_MONITOR_SERVER:maozi-cloud-basic-monitor:2000}\n        # SBA 注册账号（admin/admin）\n        username: admin\n        password: admin\n        # 优雅下线时自动从监控中心摘除\n        auto-deregistration: true\n        instance: \n          # 用 IP 注册，避免容器主机名解析不了\n          prefer-ip: true\n          metadata: \n            version: 环境:${application.environment:local} 版本:${application.version:main}\n            tags: \n              environment: ${application.environment:local}\n              version: ${application.version:main}\n\nendpoints:\n  dubbo:\n    enabled: true\n\n# Actuator 端点与指标暴露\nmanagement:\n  info.env.enabled: true\n  health:\n    dubbo:\n      status:\n        defaults: memory\n        extras: load,threadpool\n  endpoints:\n    web:\n      exposure:\n        # 暴露全部端点（仅内网/监控可达，网关侧已隔离）\n        include: \'*\'\n  endpoint:\n    serviceregistry:\n      enabled: true\n    shutdown:\n      enabled: true\n    dubbo:\n      enabled: true\n    dubbo-shutdown:\n      enabled: true\n    dubbo-configs:\n      enabled: true\n    dubbo-services:\n      enabled: true\n    dubbo-references:\n      enabled: true\n    dubbo-properties:\n      enabled: true\n    health:\n      # 健康详情全展示，能看到 DB/Redis 等组件状态\n      show-details: ALWAYS\n      probes.enabled: true\n  metrics:\n    # 指标统一打应用/实例/环境标签，Grafana 按维度聚合\n    tags:\n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${application.environment}\n    distribution:\n      percentiles-histogram:\n        http:\n          server:\n            requests: \'true\'\n  # 链路追踪（Micrometer/OTel）属性，与 metrics 标签对齐\n  observations: \n    key-values: \n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${application.environment}', '2830681157da7ef5dfbe3ce1a0cd39d3', '2026-07-03 13:54:34', '2026-10-21 14:19:47', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5645, 'cloud-oauth.yml', 'DEFAULT_GROUP', '# 资源服务器 OAuth2：不透明令牌（opaque token）内省校验模式\nspring:\n  security:\n    oauth2:\n      resourceserver:\n        opaquetoken:\n          # http 或 rpc\n          # mode: http\n          # 客户端id\n          # 内省用客户端 ID（注册在 oauth 服务），system 为默认客户端\n          client-id: system\n          # 客户端秘钥\n          # 客户端秘钥，生产环境必须更换\n          client-secret: 123456', '44b59a5cb3c35677e6546c3a0b86fcd8', '2026-07-03 13:54:34', '2026-10-21 14:19:47', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5646, 'boot-db.yml', 'DEFAULT_GROUP', '# MyBatis-Plus / MyBatis-Join / Flyway 数据访问配置\nmybatis-plus:\n  # Mapper XML 扫描路径，按项目缩写定位\n  mapper-locations: classpath:com/maozi/${application-project-abbreviation}/*/mapper/*.xml\n  # typeEnumsPackage: com.maozi.${application-project-abbreviation}.*.enums\n  configuration: \n    # 列名下划线自动转驼峰属性\n    map-underscore-to-camel-case: true\n    # SQL 日志走自定义封装，需要直出控制台时换 StdOutImpl\n    log-impl: com.maozi.db.config.MybatisPlusLog\n    # 枚举统一用 MP 通用枚举处理器\n    default-enum-type-handler: com.baomidou.mybatisplus.core.handlers.MybatisEnumTypeHandler\n    # log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config: \n    refresh: false\n    banner: false\n    db-config:\n      db-type: mysql\n      # 主键自增\n      id-type: AUTO\n      # null 字段不参与 INSERT/UPDATE\n      field-strategy: NOT_NULL\n      column-like: false\n      capital-mode: true\n      # 逻辑删除：1=已删，0=未删\n      logic-delete-value: 1\n      logic-not-delete-value: 0\n\nmybatis-plus-join:\n  banner: false\n  table-alias: main\n\nmybatis:\n  configuration:\n    cache-enabled: false\n\n# Flyway 自动建表迁移：启动时按版本号执行 classpath:db 下脚本\nspring: \n  flyway: \n    enabled: true\n    table: system_table_flyway\n    clean-disabled: true\n    out-of-order: true\n    baseline-on-migrate: true\n    baseline-version: 0\n    locations: classpath:db\n    encoding: UTF-8', 'a2d65d284279b6ff6032cbf44ff7eefa', '2026-07-03 13:54:34', '2026-10-21 14:19:47', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5647, 'maozi-cloud-system-service.yml', 'DEFAULT_GROUP', '# 系统服务自身配置\napplication:\n  title: 系统服务\n  details: 管理 用户、角色、权限、系统配置 等功能\n\n# 需要独立数据源时放开以下注释覆盖默认值（默认库：应用名-环境-db）\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n# application-datasource-db-name: maozi-cloud-system-local-db\n\n# 免认证接口白名单，多个路径逗号分隔\napplication-project-whitelist: /config/system/get\n\n# 项目公开信息（关于我们/版权栏等展示用）\napplication-project-system: \n  projectName: 小猫子脚手架\n  corporationName: 小猫子网络科技有限公司\n  icon: http://dummyimage.com/100x100\n  environment: ${application.environment}\n  description: 基于 Spring Cloud Alibaba + Dubbo 的一站式分布式解决方案开源封装，内置分布式应用开发所需全套组件，统一团队代码风格，保障代码质量，让开发者专注业务逻辑，实现高效快速开发。\n  copyright: 本网站所有权归《${application-project-system.corporationName}》所有，请勿抄袭和抄袭\n\nspring.servlet.multipart: \n  # 上传大小限制（默认仅 1MB）\n  max-file-size: 1MB\n  \n# 文件存储：阿里云 OSS（AK/SK 从环境变量注入）\noss:\n  # 路由到阿里云处理器\n  store-type: aliyun\n  aliyun:\n    access-key-id: ${APPLICATION_ALIYUN_CLIENT_ID}\n    access-key-secret: ${APPLICATION_ALIYUN_CLIENT_SECRET}\n    region: cn-beijing\n    endpoint: https://oss-cn-beijing.aliyuncs.com\n    bucket: maozi-cloud-bucket\n    #domain:                  # 可选，CDN 自定义域名', '52ffb97987f3caa4625956ba56ec2154', '2026-07-03 13:54:34', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5648, 'maozi-cloud-oauth-service.yml', 'DEFAULT_GROUP', '# 认证授权服务自身配置\napplication:\n  title: 认证授权服务\n  details: 管理 三方认证授权、客户端 等功能\n\n# 需要独立数据源时放开以下注释覆盖默认值（默认库：应用名-环境-db）\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n\n# oauth 库名显式指定（默认规则：服务名-环境-db）\napplication-datasource-db-name: maozi-cloud-oauth-local-db\n\n# application-project-whitelist: ', 'd8be8a6ec9ae0e29e85e82b78258eb15', '2026-07-03 13:54:34', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5649, 'maozi-cloud-gateway-service.yml', 'DEFAULT_GROUP', '# 网关服务：流量入口，端口固定 1100\napplication:\n  # 对外统一入口端口\n  port: 1100\n  title: 网关服务\n  details: 处理 流量分发、黑白名单、流控 等功能\n\n# Sentinel 网关流控 + Spring Cloud Gateway 路由\nspring: \n  cloud:\n    sentinel:\n      # 规则数据源前缀：应用名-环境-版本（规则统一存 middleware 命名空间 SENTINEL_GROUP）\n      name: ${spring.application.name}-${application.environment:local}-${application.version:main}\n      # 启动即注册到控制台，不等首次请求\n      eager: true\n      transport:\n        port: 8719\n        dashboard: ${APPLICATION_SENTINEL_SERVER:maozi-cloud-basic-sentinel:8858}\n      # 关闭普通 Web 限流过滤，网关场景走 gateway 维度规则\n      filter:\n        enabled: false\n      # 规则持久化：控制台改动写回 Nacos，客户端监听变更实时生效\n      datasource:\n        # 流控规则\n        flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-flow-rules.json\n            rule-type: flow\n        # 熔断降级规则\n        degrade:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-degrade-rules.json\n            rule-type: degrade\n        # 热点参数限流规则\n        param-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-param-rules.json\n            rule-type: param-flow\n        # 系统自适应保护规则\n        system:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-system-rules.json\n            rule-type: system\n        # 黑白名单授权规则\n        authority:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            data-id: ${spring.cloud.sentinel.name}-authority-rules.json\n            rule-type: authority\n        # 网关维度流控（按 route/API 组限流）\n        gw-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            dataId: ${spring.cloud.sentinel.name}-gw-flow-rules.json\n            groupId: SENTINEL_GROUP\n            rule-type: gw-flow\n        # 网关 API 分组（多个路径归成一组统一限流）\n        gw-api-group:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            dataId: ${spring.cloud.sentinel.name}-gw-api-group-rules.json\n            groupId: SENTINEL_GROUP\n            rule-type: gw-api-group\n\n    gateway:\n      httpclient:\n        # 建立 TCP 连接的超时时间\n        connect-timeout: 1000\n        # 从连接成功开始，到收到后端完整响应的总超时\n        response-timeout: 30s\n\n      discovery:\n        locator:\n          # 按服务名自动建路由（/服务名/** 兜底转发到对应服务）\n          enabled: true\n\n      # 默认过滤器：对所有路由生效\n      default-filters:\n      # 去掉第一段路径前缀（/system/xxx → /xxx）再转发\n      - StripPrefix=1\n      - name: Retry\n        # 网关类错误（GET/POST）自动重试 1 次\n        args:\n          retries: 1\n          methods: \n            - GET\n            - POST\n          statuses: \n            - BAD_GATEWAY\n            - GATEWAY_TIMEOUT\n            - SERVICE_UNAVAILABLE\n          exceptions: \n            - java.net.ConnectException\n            - org.springframework.cloud.gateway.support.NotFoundException\n            - reactor.netty.http.client.PrematureCloseException\n\n\n      # 显式路由：路径前缀 → 服务（新增服务照此加一段）\n      routes: \n        # 系统服务\n        - id: MAOZI-CLOUD-SYSTEM\n          uri: lb://maozi-cloud-system-service\n          predicates:\n          - Path=/system/**\n\n        # 认证服务\n        - id: MAOZI-CLOUD-OAUTH\n          uri: lb://maozi-cloud-oauth-service\n          predicates:\n          - Path=/oauth/**\n\n        # AI 服务\n        - id: MAOZI-CLOUD-AI-SERVICE\n          uri: lb://maozi-cloud-ai-service\n          predicates:\n          - Path=/ai/**', '21dd4a9fa296fa4c3de2c4519fe02721', '2026-07-03 13:54:34', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5772, 'boot-datasource.yml', 'DEFAULT_GROUP', 'spring:\n  datasource:\n    # 连接池实现类，HikariCP 是 Spring Boot 2.x 起的默认连接池，主打轻量高性能\n    type: com.zaxxer.hikari.HikariDataSource\n    # MySQL 8.x 驱动（Connector/J 8+ 类名带 cj，5.x 是 com.mysql.jdbc.Driver）\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    # JDBC 连接串，主机/库名支持占位符覆盖，不覆盖时取默认值：\n    #   主机端口 -> ${application-datasource-jdbc-url}，默认容器内基础 MySQL 服务\n    #   库名 -> ${application-datasource-db-name}，默认「应用名-环境-db」，每个服务独立库\n    # 连接参数：\n    #   useSSL=false             内网直连关闭 SSL，避免自签证书告警\n    #   serverTimezone=Asia/Shanghai  指定时区，不配可能报时区无法识别或时间偏差8小时\n    #   characterEncoding=utf8   字符编码\n    #   nullCatalogMeansCurrent=true  元数据查询只查当前库；MySQL 8 驱动默认 false 会扫出所有库，影响代码生成器/Flyway 等按 catalog 查表的场景\n    url: jdbc:mysql://${application-datasource-jdbc-url:maozi-cloud-basic-mysql:3306}/${application-datasource-db-name:${spring.application.name}-${application.environment}-db}?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8&nullCatalogMeansCurrent=true\n    # 账号密码，生产环境通过配置中心/环境变量覆盖，这里仅本地默认值\n    username: ${application-datasource-jdbc-username:root}\n    password: ${application-datasource-jdbc-password:password}\n    # Hikari 连接池参数\n    hikari:\n      # 最大连接，根据业务压测调整，默认推荐10~20，不要直接50\n      maximum-pool-size: 15\n      # 获取连接等待超时时间（6s），池耗尽时最多等这么久，超时抛异常快速失败，避免请求线程被长时间挂起\n      connection-timeout: 6000\n      # 不配置minimum-idle，Hikari官方推荐，最小空闲连接等于最大连接（固定大小池，避免频繁建连）\n      # minimum-idle: 10\n      # 空闲连接超时（5min），注意必须小于max-lifetime\n      idle-timeout: 300000\n      # 连接最大存活时间（540s=9min），比mysql wait_timeout小至少60s，到期连接异步关闭重建，避免拿到已被服务端断开的连接\n      max-lifetime: 540000\n      # 删掉 connection-test-query，Hikari用JDBC4 isValid校验', '68b1e0da70513fae5ff90b2fef4e8ef6', '2026-07-03 14:33:55', '2026-10-21 14:01:01', NULL, '172.18.0.1', '', 'dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5773, 'boot-elasticsearch.yml', 'DEFAULT_GROUP', '# Elasticsearch 连接配置（当前未接入 ES，接入时调整地址后由对应 starter 加载）\nspring:\n  data:\n    elasticsearch:\n    ####集群名称\n     cluster-name: maozi-cloud-es\n    ####地址 \n     cluster-nodes: 192.168.0.1,192.168.0.2', 'b7f02bc256acdd0743ff8c965b8e9f1d', '2026-07-03 14:33:55', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5775, 'boot-redis.yml', 'DEFAULT_GROUP', '# Redis 连接配置：地址/密码均可通过环境变量覆盖，默认指向容器内基础 Redis\nspring:\n  data:\n    redis:\n      # Redis 地址（本地直连时用环境变量 APPLICATION_REDIS_SERVER=127.0.0.1 覆盖）\n      host: ${APPLICATION_REDIS_SERVER:maozi-cloud-basic-redis}\n      port: ${APPLICATION_REDIS_PORT:6379}\n      # 密码从环境变量读取，禁止硬编码\n      password: ${APPLICATION_REDIS_SERVER_PASSWORD:password}\n      # 逻辑库编号（0~15），按环境/业务做数据隔离\n      database: ${APPLICATION_REDIS_SERVER_DATABASE:0}\n      # 可选，客户端标识，方便redis client list排查\n      client-name: ${spring.application.name}-${application.environment}-${application.version}\n      lettuce:\n        # 命令超时，建议500ms，根据业务微调，不要超过1s\n        timeout: 500ms\n        shutdown-timeout: 300ms\n        pool:\n          # 最大活跃连接，根据单实例QPS，一般80~200\n          max-active: 120\n          # 获取连接最大等待时间1s\n          max-wait: 1000ms\n          max-idle: 60\n          # 维持少量预热连接\n          min-idle: 10', '09b93eeca64b2d1aa16848a2221aa0b7', '2026-07-03 14:33:55', '2026-10-21 16:07:17', NULL, '172.18.0.1', '', 'dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5797, 'cloud-default.yml', 'DEFAULT_GROUP', '# 所有服务共用的兜底配置：Web容器、优雅停机、序列化、Feign、日志级别（服务自身 yml 可覆盖）\nserver:\n  port: ${APPLICATION_PORT:${application.port:0}}\n  # 出错/找不到处理器时的统一转发路径\n  error.path: /application/error\n  # graceful=优雅停机 / immediate=立刻关闭\n  shutdown: graceful\n  undertow:\n    # 单个请求超时时间，单位毫秒\n    request-timeout: 30000\n  # compression:\n  #   enabled: true\n  #   min-response-size: 1024\n  #   mime-types: application/json,application/xml,text/html,text/xml,text/plain\n\nspring:\n  lifecycle:\n    # 优雅停机等待最大超时时间，按需调整，一般10~30s\n    timeout-per-shutdown-phase: 65s\n  main:\n    # 关闭 banner 与启动日志，保持控制台干净\n    banner-mode: off\n    log-startup-info: false\n  web:\n    resources:\n      # 不映射静态资源，纯接口服务\n      add-mappings: false\n  mvc: \n    # 404 抛 NoHandlerFoundException，交给全局异常处理器\n    throw-exception-if-no-handler-found: true\n    # ANT 路径匹配策略，兼容文档工具的老写法\n    pathmatch.matching-strategy: ant_path_matcher\n  # 全局 JSON 序列化：时区/日期格式统一，null 字段不输出\n  jackson: \n    time-zone: GMT+8\n    date-format: yyyy-MM-dd HH:mm:ss\n    default-property-inclusion: NON_NULL\n\n# OpenFeign 远程调用\nfeign:\n  sentinel:\n    enabled: true\n  # 底层 HTTP 客户端用 OkHttp（优于默认实现），禁用 HttpClient\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  # 默认超时 30s，按下游实际耗时调整\n  client:\n    config:\n      default:\n        connectTimeout: 30000\n        readTimeout: 30000\n  compression:\n    request:\n      # 开启请求数据的压缩功能\n      enabled: true\n      # 最小压缩值标准，当数据大于 1024 才会进行压缩\n      min-request-size: 1024\n      # 压缩类型\n      mime-types: text/xml,application/xml,application/json\n    response:\n      enabled: true\n\n# 日志级别：根 ERROR、业务包 INFO、Dubbo 注册/通信日志关闭\nlogging: \n  level: \n    root: ERROR\n    com.maozi: INFO\n    org.apache.dubbo.registry: OFF\n    org.apache.dubbo.remoting: OFF', '54091f124116f7232eeb3cdc06e6f5e2', '2026-07-03 14:33:55', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5798, 'cloud-dubbo.yml', 'DEFAULT_GROUP', '# Dubbo RPC 配置：应用、扫描、协议、超时、注册中心\ndubbo:\n  application: \n    name: dubbo-${spring.application.name}\n    # instance/interface/all\n    register-mode: instance\n    # 应用版本（随 application.version），用于版本路由/灰度\n    version: ${application.version:main}\n    # 内网环境关闭序列化安全检查，避免自定义实体校验报错\n    serialize-check-status: DISABLE\n    check-serializable: false\n  # RPC 实现类扫描包，按项目缩写拼接（如 system → com.maozi.system.*.api.impl.rpc）\n  scan:\n    base-packages: com.maozi.${application-project-abbreviation}.*.api.impl.rpc\n  # 通信协议：dubbo；需要 Triple/gRPC 协议时放开上面 tri 注释\n  protocol:\n    # name: tri\n    name: dubbo\n    # Dubbo 端口，-1=随机；固定端口用 APPLICATION_DUBBO_PORT / application.dubbo.port 指定\n    port: ${APPLICATION_DUBBO_PORT:${application.dubbo.port:-1}}\n  provider:\n    # 提供方默认超时 30s，联调环境容忍慢接口\n    timeout: 30000\n    # 自定义过滤器：服务端还原用户/链路上下文\n    filter: applicationDubboContextLoadFilter\n    # 序列化统一 hessian2，避免多协议协商问题\n    prefer-serialization: hessian2\n    serialization: hessian2\n  consumer:\n    # 启动不检查依赖方是否在线，解除服务启动顺序耦合\n    check: false\n    # 消费方默认超时 30s\n    timeout: 30000\n    # 失败自动重试 1 次，非幂等接口记得在 @DubboReference 上单独关闭\n    retries: 1\n    # 自定义过滤器：消费端透传用户/链路上下文\n    filter: applicationDubboContextTransmitFilter\n  # 注册中心复用 Nacos（与配置中心同实例），namespace 随环境隔离\n  registry:\n    address: nacos://${spring.cloud.nacos.discovery.server-addr}?namespace=${spring.cloud.nacos.discovery.namespace}', '438b2f0b11550ed4e1d58961e31f302c', '2026-07-03 14:33:55', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5799, 'cloud-nacos.yml', 'DEFAULT_GROUP', '# Nacos 服务发现配置\nspring: \n  cloud: \n    nacos: \n      discovery:\n        enabled: true\n        register-enabled: true\n        # 实例元数据带版本号，灰度路由按此筛选实例\n        metadata: \n          version: ${application.version:main}', '111d89ef9c371c69bba00d1c1671f74c', '2026-07-03 14:33:55', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5800, 'cloud-rocket.yml', 'DEFAULT_GROUP', '# RocketMQ 配置（当前未启用，接入 MQ 时改 name-server 并由对应 starter 加载）\nspring:\n  cloud:\n    stream:\n      rocketmq:\n        binder:\n          # access-key: \n          # secret-key: \n          name-server: localhost:9876\n# rocketmq:\n  # instance:\n    # id: \n    # name: ', '79542009b0f9f0671e3dc245bbf7022b', '2026-07-03 14:33:55', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5801, 'cloud-sentinel.yml', 'DEFAULT_GROUP', '# RestTemplate 请求也纳入 Sentinel 保护\nresttemplate:\n  sentinel:\n    enabled: true\n\nfeign:\n  # Feign 接口接入 Sentinel 熔断降级\n  sentinel: \n    enabled: true\n\n# Sentinel 客户端：控制台接入 + 规则持久化到 Nacos\nspring: \n  cloud: \n    sentinel:\n      # 规则数据源前缀：应用名-环境-版本（规则统一存 middleware 命名空间 SENTINEL_GROUP）\n      name: ${spring.application.name}-${application.environment:local}-${application.version:main}\n      # 启动即注册到控制台，不等首次请求\n      eager: true\n      transport:\n        # 与控制台通信的本地端口，被占用会自动顺延\n        port: 8719\n        # Sentinel 控制台地址\n        dashboard: ${APPLICATION_SENTINEL_SERVER:maozi-cloud-basic-sentinel:8858}\n      # 资源名带 HTTP 方法（如 GET:/user/info），避免同路径不同方法混淆\n      http-method-specify: true\n      # 规则持久化：控制台改动写回 Nacos，客户端监听变更实时生效\n      datasource:\n        # 流控规则\n        flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-flow-rules.json\n            rule-type: flow\n        # 熔断降级规则\n        degrade:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-degrade-rules.json\n            rule-type: degrade\n        # 热点参数限流规则\n        param-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-param-rules.json\n            rule-type: param-flow\n        # 系统自适应保护规则\n        system:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-system-rules.json\n            rule-type: system\n        # 黑白名单授权规则\n        authority:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            data-id: ${spring.cloud.sentinel.name}-authority-rules.json\n            rule-type: authority', '84ec3b202774d7cf612226b52eaadeb3', '2026-07-03 14:33:55', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5864, 'boot-arthas.yml', 'DEFAULT_GROUP', '# Arthas 在线诊断：通过 Tunnel Server 远程连接排查问题\narthas: \n  # 在 Tunnel 面板里的唯一标识，用应用名方便定位\n  agent-id: ${spring.application.name}\n  # Tunnel Server 地址（本地 7777，容器环境替换为 tunnel 服务地址）\n  tunnel-server: ws://localhost:7777/ws\n  # -1=不开启本地 telnet/http 端口，只走 Tunnel\n  telnet-port: -1\n  http-port: -1', '8e12074f821ddc3b85a0de0fb2e2990a', '2026-07-03 14:33:55', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5865, 'boot-lock.yml', 'DEFAULT_GROUP', '# Redisson 分布式锁：复用 Redis 连接配置\nlock:\n  redisson:\n    # 锁实例与 spring.data.redis 同源，改 Redis 配置时这里自动跟随\n    address: redis://${spring.data.redis.host}:${spring.data.redis.port}\n    password: ${spring.data.redis.password}\n    database: ${spring.data.redis.database:0}\n    # waitTime: 60 #获取锁最长阻塞时间（默认：60，单位：秒）\n    # leaseTime: 60 #已获取锁后自动释放时间（默认：60，单位：秒）\n    # redis集群配置 如 redis://127.0.0.1:7000,redis://127.0.0.1:7001,redis://127.0.0.1:7002\n    # spring.klock.address 和 spring.klock.cluster-server.node-addresses 选其一即可\n    # cluster-server.node-addresses:', '31e5dee8e68b08adceb533597727ddeb', '2026-07-03 14:33:55', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5866, 'boot-monitor.yml', 'DEFAULT_GROUP', '# 监控客户端：注册到 Spring Boot Admin + Actuator 端点暴露\nspring:  \n  boot: \n    admin: \n      client:\n        # SBA 服务端地址，启动后自动注册\n        url: http://${APPLICATION_MONITOR_SERVER:maozi-cloud-basic-monitor:2000}\n        # SBA 注册账号（admin/admin）\n        username: admin\n        password: admin\n        # 优雅下线时自动从监控中心摘除\n        auto-deregistration: true\n        instance: \n          # 用 IP 注册，避免容器主机名解析不了\n          prefer-ip: true\n          metadata: \n            version: 环境:${application.environment:local} 版本:${application.version:main}\n            tags: \n              environment: ${application.environment:local}\n              version: ${application.version:main}\n\nendpoints:\n  dubbo:\n    enabled: true\n\n# Actuator 端点与指标暴露\nmanagement:\n  info.env.enabled: true\n  health:\n    dubbo:\n      status:\n        defaults: memory\n        extras: load,threadpool\n  endpoints:\n    web:\n      exposure:\n        # 暴露全部端点（仅内网/监控可达，网关侧已隔离）\n        include: \'*\'\n  endpoint:\n    serviceregistry:\n      enabled: true\n    shutdown:\n      enabled: true\n    dubbo:\n      enabled: true\n    dubbo-shutdown:\n      enabled: true\n    dubbo-configs:\n      enabled: true\n    dubbo-services:\n      enabled: true\n    dubbo-references:\n      enabled: true\n    dubbo-properties:\n      enabled: true\n    health:\n      # 健康详情全展示，能看到 DB/Redis 等组件状态\n      show-details: ALWAYS\n      probes.enabled: true\n  metrics:\n    # 指标统一打应用/实例/环境标签，Grafana 按维度聚合\n    tags:\n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${application.environment}\n    distribution:\n      percentiles-histogram:\n        http:\n          server:\n            requests: \'true\'\n  # 链路追踪（Micrometer/OTel）属性，与 metrics 标签对齐\n  observations: \n    key-values: \n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${application.environment}', '2830681157da7ef5dfbe3ce1a0cd39d3', '2026-07-03 14:33:55', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5867, 'cloud-oauth.yml', 'DEFAULT_GROUP', '# 资源服务器 OAuth2：不透明令牌（opaque token）内省校验模式\nspring:\n  security:\n    oauth2:\n      resourceserver:\n        opaquetoken:\n          # http 或 rpc\n          # mode: http\n          # 客户端id\n          # 内省用客户端 ID（注册在 oauth 服务），system 为默认客户端\n          client-id: system\n          # 客户端秘钥\n          # 客户端秘钥，生产环境必须更换\n          client-secret: 123456', '44b59a5cb3c35677e6546c3a0b86fcd8', '2026-07-03 14:33:55', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5868, 'boot-db.yml', 'DEFAULT_GROUP', '# MyBatis-Plus / MyBatis-Join / Flyway 数据访问配置\nmybatis-plus:\n  # Mapper XML 扫描路径，按项目缩写定位\n  mapper-locations: classpath:com/maozi/${application-project-abbreviation}/*/mapper/*.xml\n  # typeEnumsPackage: com.maozi.${application-project-abbreviation}.*.enums\n  configuration: \n    # 列名下划线自动转驼峰属性\n    map-underscore-to-camel-case: true\n    # SQL 日志走自定义封装，需要直出控制台时换 StdOutImpl\n    log-impl: com.maozi.db.config.MybatisPlusLog\n    # 枚举统一用 MP 通用枚举处理器\n    default-enum-type-handler: com.baomidou.mybatisplus.core.handlers.MybatisEnumTypeHandler\n    # log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config: \n    refresh: false\n    banner: false\n    db-config:\n      db-type: mysql\n      # 主键自增\n      id-type: AUTO\n      # null 字段不参与 INSERT/UPDATE\n      field-strategy: NOT_NULL\n      column-like: false\n      capital-mode: true\n      # 逻辑删除：1=已删，0=未删\n      logic-delete-value: 1\n      logic-not-delete-value: 0\n\nmybatis-plus-join:\n  banner: false\n  table-alias: main\n\nmybatis:\n  configuration:\n    cache-enabled: false\n\n# Flyway 自动建表迁移：启动时按版本号执行 classpath:db 下脚本\nspring: \n  flyway: \n    enabled: true\n    table: system_table_flyway\n    clean-disabled: true\n    out-of-order: true\n    baseline-on-migrate: true\n    baseline-version: 0\n    locations: classpath:db\n    encoding: UTF-8', 'a2d65d284279b6ff6032cbf44ff7eefa', '2026-07-03 14:33:55', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5869, 'maozi-cloud-system-service.yml', 'DEFAULT_GROUP', '# 系统服务自身配置\napplication:\n  title: 系统服务\n  details: 管理 用户、角色、权限、系统配置 等功能\n\n# 需要独立数据源时放开以下注释覆盖默认值（默认库：应用名-环境-db）\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n# application-datasource-db-name: maozi-cloud-system-dev-db\n\n# 免认证接口白名单，多个路径逗号分隔\napplication-project-whitelist: /config/system/get\n\n# 项目公开信息（关于我们/版权栏等展示用）\napplication-project-system:\n  projectName: 小猫子脚手架\n  corporationName: 小猫子网络科技有限公司\n  icon: http://dummyimage.com/100x100\n  environment: ${application.environment}\n  description: 基于 Spring Cloud Alibaba + Dubbo 的一站式分布式解决方案开源封装，内置分布式应用开发所需全套组件，统一团队代码风格，保障代码质量，让开发者专注业务逻辑，实现高效快速开发。\n  copyright: 本网站所有权归《${application-project-system.corporationName}》所有，请勿抄袭和抄袭\n\nspring.servlet.multipart: \n  # 上传大小限制（默认仅 1MB）\n  max-file-size: 1MB\n  \n# 文件存储：阿里云 OSS（AK/SK 从环境变量注入）\noss:\n  # 路由到阿里云处理器\n  store-type: aliyun\n  aliyun:\n    access-key-id: ${APPLICATION_ALIYUN_CLIENT_ID}\n    access-key-secret: ${APPLICATION_ALIYUN_CLIENT_SECRET}\n    region: cn-beijing\n    endpoint: https://oss-cn-beijing.aliyuncs.com\n    bucket: maozi-cloud-bucket\n    #domain:                  # 可选，CDN 自定义域名', '4268e5f06554df28185dd717288a579d', '2026-07-03 14:33:55', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5870, 'maozi-cloud-oauth-service.yml', 'DEFAULT_GROUP', '# 认证授权服务自身配置\napplication:\n  title: 认证授权服务\n  details: 管理 三方认证授权、客户端 等功能\n\n# 需要独立数据源时放开以下注释覆盖默认值（默认库：应用名-环境-db）\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n\n# application-datasource-db-name: maozi-cloud-oauth-dev-db\n\n# application-project-whitelist: ', 'e50b5e3c05168037740865c3a6741633', '2026-07-03 14:33:55', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5871, 'maozi-cloud-gateway-service.yml', 'DEFAULT_GROUP', '# 网关服务：流量入口，端口固定 1100\napplication:\n  # 对外统一入口端口\n  port: 1100\n  title: 网关服务\n  details: 处理 流量分发、黑白名单、流控 等功能\n\n# Sentinel 网关流控 + Spring Cloud Gateway 路由\nspring: \n  cloud:\n    sentinel:\n      # 规则数据源前缀：应用名-环境-版本（规则统一存 middleware 命名空间 SENTINEL_GROUP）\n      name: ${spring.application.name}-${application.environment:local}-${application.version:main}\n      # 启动即注册到控制台，不等首次请求\n      eager: true\n      transport:\n        port: 8719\n        dashboard: ${APPLICATION_SENTINEL_SERVER:maozi-cloud-basic-sentinel:8858}\n      # 关闭普通 Web 限流过滤，网关场景走 gateway 维度规则\n      filter:\n        enabled: false\n      # 规则持久化：控制台改动写回 Nacos，客户端监听变更实时生效\n      datasource:\n        # 流控规则\n        flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-flow-rules.json\n            rule-type: flow\n        # 熔断降级规则\n        degrade:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-degrade-rules.json\n            rule-type: degrade\n        # 热点参数限流规则\n        param-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-param-rules.json\n            rule-type: param-flow\n        # 系统自适应保护规则\n        system:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-system-rules.json\n            rule-type: system\n        # 黑白名单授权规则\n        authority:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            data-id: ${spring.cloud.sentinel.name}-authority-rules.json\n            rule-type: authority\n        # 网关维度流控（按 route/API 组限流）\n        gw-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            dataId: ${spring.cloud.sentinel.name}-gw-flow-rules.json\n            groupId: SENTINEL_GROUP\n            rule-type: gw-flow\n        # 网关 API 分组（多个路径归成一组统一限流）\n        gw-api-group:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            dataId: ${spring.cloud.sentinel.name}-gw-api-group-rules.json\n            groupId: SENTINEL_GROUP\n            rule-type: gw-api-group\n\n    gateway:\n      httpclient:\n        # 建立 TCP 连接的超时时间\n        connect-timeout: 1000\n        # 从连接成功开始，到收到后端完整响应的总超时\n        response-timeout: 30s\n\n      discovery:\n        locator:\n          # 按服务名自动建路由（/服务名/** 兜底转发到对应服务）\n          enabled: true\n\n      # 默认过滤器：对所有路由生效\n      default-filters:\n      # 去掉第一段路径前缀（/system/xxx → /xxx）再转发\n      - StripPrefix=1\n      - name: Retry\n        # 网关类错误（GET/POST）自动重试 1 次\n        args:\n          retries: 1\n          methods: \n            - GET\n            - POST\n          statuses: \n            - BAD_GATEWAY\n            - GATEWAY_TIMEOUT\n            - SERVICE_UNAVAILABLE\n          exceptions: \n            - java.net.ConnectException\n            - org.springframework.cloud.gateway.support.NotFoundException\n            - reactor.netty.http.client.PrematureCloseException\n\n\n      # 显式路由：路径前缀 → 服务（新增服务照此加一段）\n      routes: \n        # 系统服务\n        - id: MAOZI-CLOUD-SYSTEM\n          uri: lb://maozi-cloud-system-service\n          predicates:\n          - Path=/system/**\n\n        # 认证服务\n        - id: MAOZI-CLOUD-OAUTH\n          uri: lb://maozi-cloud-oauth-service\n          predicates:\n          - Path=/oauth/**\n\n        # AI 服务\n        - id: MAOZI-CLOUD-AI-SERVICE\n          uri: lb://maozi-cloud-ai-service\n          predicates:\n          - Path=/ai/**', '21dd4a9fa296fa4c3de2c4519fe02721', '2026-07-03 14:33:55', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (6375, 'cloud-seata.yml', 'DEFAULT_GROUP', '# Seata 分布式事务客户端\nseata:\n  # 开启后 @GlobalTransactional 才生效\n  enabled: true\n  # 应用标识\n  application-id: ${spring.application.name}\n  # 事务分组：maozi-cloud-{环境}-tx-group，与 middleware 命名空间 seata.properties 的 vgroupMapping 对应\n  tx-service-group: maozi-cloud-${application.environment}-tx-group\n  # Seata 自身配置从 Nacos middleware 命名空间 SEATA_GROUP 读取 seata.properties\n  config:\n    type: nacos\n    nacos:\n      serverAddr: ${spring.cloud.nacos.config.server-addr}\n      namespace: middleware\n      group: SEATA_GROUP\n      dataId: seata.properties\n      username: \'nacos\'\n      password: \'nacos\'\n  # 注册中心：按应用名 maozi-cloud-basic-seata 在 middleware 命名空间发现 seata-server\n  registry:\n    type: nacos\n    nacos:\n      application: maozi-cloud-basic-seata\n      server-addr: ${spring.cloud.nacos.discovery.server-addr}\n      namespace: middleware\n      group: SEATA_GROUP\n      username: \'nacos\'\n      password: \'nacos\'', 'e36e0b6cab959567ea25e1b1eed83e8a', '2026-07-13 11:51:00', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (6377, 'seata.properties', 'SEATA_GROUP', '# 存储模式 db：全局事务/分支/全局锁落库，重启不丢，生产推荐\nstore.mode=db\n#-----db-----\n# 事务日志存储库连接（独立库 maozi-cloud-seata-middleware-db，建库脚本在 maozi-cloud-basic-seata 目录）\nstore.db.datasource=druid\nstore.db.dbType=mysql\n# 需要根据mysql的版本调整driverClassName\n# mysql8及以上版本对应的driver：com.mysql.cj.jdbc.Driver\n# mysql8以下版本的driver：com.mysql.jdbc.Driver\nstore.db.driverClassName=com.mysql.cj.jdbc.Driver\nstore.db.url=jdbc:mysql://maozi-cloud-basic-mysql:3306/maozi-cloud-seata-middleware-db?useUnicode=true&characterEncoding=utf8&connectTimeout=1000&socketTimeout=3000&autoReconnect=true&useSSL=false\nstore.db.user=root\nstore.db.password=password\n# 数据库初始连接数\nstore.db.minConn=1\n# 数据库最大连接数\nstore.db.maxConn=20\n# 获取连接时最大等待时间 默认5000，单位毫秒\nstore.db.maxWait=5000\n# 全局事务表名 默认global_table\nstore.db.globalTable=global_table\n# 分支事务表名 默认branch_table\nstore.db.branchTable=branch_table\n# 全局锁表名 默认lock_table\nstore.db.lockTable=lock_table\n# 查询全局事务一次的最大条数 默认100\nstore.db.queryLimit=100\n\n\n# 事务分组 → 集群映射：local/dev 环境的事务组都路由到 default 集群\nservice.vgroupMapping.maozi-cloud-local-tx-group=default\nservice.vgroupMapping.maozi-cloud-dev-tx-group=default\n# undo保留天数 默认7天,log_status=1（附录3）和未正常清理的undo\nserver.undo.logSaveDays=7\n# undo清理线程间隔时间 默认86400000，单位毫秒\nserver.undo.logDeletePeriod=86400000\n# 二阶段提交重试超时时长 单位ms,s,m,h,d,对应毫秒,秒,分,小时,天,默认毫秒。默认值-1表示无限重试\n# 公式: timeout>=now-globalTransactionBeginTime,true表示超时则不再重试\n# 注: 达到超时时间后将不会做任何重试,有数据不一致风险,除非业务自行可校准数据,否者慎用\nserver.maxCommitRetryTimeout=-1\n# 二阶段回滚重试超时时长\nserver.maxRollbackRetryTimeout=-1\n# 二阶段提交未完成状态全局事务重试提交线程间隔时间 默认1000，单位毫秒\nserver.recovery.committingRetryPeriod=1000\n# 二阶段异步提交状态重试提交线程间隔时间 默认1000，单位毫秒\nserver.recovery.asynCommittingRetryPeriod=1000\n# 二阶段回滚状态重试回滚线程间隔时间  默认1000，单位毫秒\nserver.recovery.rollbackingRetryPeriod=1000\n# 超时状态检测重试线程间隔时间 默认1000，单位毫秒，检测出超时将全局事务置入回滚会话管理器\nserver.recovery.timeoutRetryPeriod=1000', '54d407a16bd1752136ab4b7f0ad965ff', '2026-07-13 12:01:58', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'middleware', NULL, NULL, NULL, 'properties', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (6446, 'cloud-seata.yml', 'DEFAULT_GROUP', '# Seata 分布式事务客户端\nseata:\n  # 开启后 @GlobalTransactional 才生效\n  enabled: true\n  # 应用标识\n  application-id: ${spring.application.name}\n  # 事务分组：maozi-cloud-{环境}-tx-group，与 middleware 命名空间 seata.properties 的 vgroupMapping 对应\n  tx-service-group: maozi-cloud-${application.environment}-tx-group\n  # Seata 自身配置从 Nacos middleware 命名空间 SEATA_GROUP 读取 seata.properties\n  config:\n    type: nacos\n    nacos:\n      serverAddr: ${spring.cloud.nacos.config.server-addr}\n      namespace: middleware\n      group: SEATA_GROUP\n      dataId: seata.properties\n      username: \'nacos\'\n      password: \'nacos\'\n  # 注册中心：按应用名 maozi-cloud-basic-seata 在 middleware 命名空间发现 seata-server\n  registry:\n    type: nacos\n    nacos:\n      application: maozi-cloud-basic-seata\n      server-addr: ${spring.cloud.nacos.discovery.server-addr}\n      namespace: middleware\n      group: SEATA_GROUP\n      username: \'nacos\'\n      password: \'nacos\'', 'e36e0b6cab959567ea25e1b1eed83e8a', '2026-07-15 15:45:15', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (6836, 'maozi-cloud-ai-service.yml', 'DEFAULT_GROUP', '# AI 服务自身配置\napplication:\n  title: AI服务\n  details: 与AI交互、管理AI对话记忆、AI知识库、AI提示词等\n\n# 需要独立数据源时放开以下注释覆盖默认值（默认库：应用名-环境-db）\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n# application-datasource-db-name: maozi-cloud-system-local-db\n\n# Spring AI 模型接入：默认 DashScope，zhipuai/openai 保留注释可切换\nspring: \n  ai: \n    # zhipuai: \n    #   base-url: https://api.z.ai/api/paas\n    #   api-key: \n    #   chat:\n    #     options:\n    #       model: glm-5.2\n    #   embedding:\n    #     enabled: false\n    dashscope: \n      # 百炼 API Key，从环境变量注入，禁止写死在配置里\n      api-key: ${APPLICATION_AI_DASHSCOPE_KEY}\n      chat: \n        enabled: true\n        options: \n          model: qwen-max\n          text_image_model: qwen-vl-max\n      # 向量模型默认关闭，知识库/RAG 场景再打开\n      embedding: \n        enabled: false\n        options: \n          model: text-embedding-v3\n          dimensions: 1024\n    # openai: \n    #   base-url: \n    #   api-key: \n    #   chat: \n    #     options: \n    #       model: gpt\n    #   embedding:\n    #     enabled: false', '0fc57250749259fc2734d5b8c754d281', '2026-08-15 19:47:49', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (7027, 'maozi-cloud-ai-service.yml', 'DEFAULT_GROUP', '# AI 服务自身配置\napplication:\n  title: AI服务\n  details: 与AI交互、管理AI对话记忆、AI知识库、AI提示词等\n\n# 需要独立数据源时放开以下注释覆盖默认值（默认库：应用名-环境-db）\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n# application-datasource-db-name: maozi-cloud-system-local-db\n\n# Spring AI 模型接入：默认 DashScope，zhipuai/openai 保留注释可切换\nspring: \n  ai: \n    # zhipuai: \n    #   base-url: https://api.z.ai/api/paas\n    #   api-key: \n    #   chat:\n    #     options:\n    #       model: glm-5.2\n    #   embedding:\n    #     enabled: false\n    dashscope: \n      # 百炼 API Key，从环境变量注入，禁止写死在配置里\n      api-key: ${APPLICATION_AI_DASHSCOPE_KEY}\n      chat: \n        enabled: true\n        options: \n          model: qwen-max\n          text_image_model: qwen-vl-max\n      # 向量模型默认关闭，知识库/RAG 场景再打开\n      embedding: \n        enabled: false\n        options: \n          model: text-embedding-v3\n          dimensions: 1024\n    # openai: \n    #   base-url: \n    #   api-key: \n    #   chat: \n    #     options: \n    #       model: gpt\n    #   embedding:\n    #     enabled: false', '0fc57250749259fc2734d5b8c754d281', '2026-08-21 08:04:30', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (7485, 'boot-snailjob.yml', 'DEFAULT_GROUP', '# SnailJob 客户端：分布式重试/任务调度\nsnail-job:\n  # 任务调度服务器信息\n  server:\n    # 服务器IP地址（或域名）；集群时建议通过 nginx 做负载均衡\n    host: ${SNAIL_JOB_SERVER:maozi-cloud-basic-snailjob}\n    # 服务器通讯端口（不是后台管理页面服务端口）\n    port: 17888\n  # 命名空间 【上面配置的空间的唯一标识】\n  namespace: ${application.environment}\n  # 接入组名【上面配置的组名称】注意: 若通过注解配置了这里的配置不生效\n  group: ${spring.application.name}-${application.version:main}\n  # 接入组 token 【上面配置的token信息】\n  token: SJ_Wyz3dmsdbDOkDujOTSSoBjGQP1BMsVnj\n  # 客户端绑定IP，必须服务器可以访问到；默认自动推断，在服务器无法调度客户端时需要手动配置\n#   host: 127.0.0.1\n  # 客户端通讯端口，默认 17889\n  port: 17889\n\n  # 实例标签带版本号，控制台可按版本筛选\n  labels:\n    version: ${application.version:main}', 'e7531d54aab1e483cdefa891148db82b', '2026-09-02 18:23:48', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (7523, 'boot-snailjob.yml', 'DEFAULT_GROUP', '# SnailJob 客户端：分布式重试/任务调度\nsnail-job:\n  # 任务调度服务器信息\n  server:\n    # 服务器IP地址（或域名）；集群时建议通过 nginx 做负载均衡\n    host: ${SNAIL_JOB_SERVER:maozi-cloud-basic-snailjob}\n    # 服务器通讯端口（不是后台管理页面服务端口）\n    port: 17888\n  # 命名空间 【上面配置的空间的唯一标识】\n  namespace: ${application.environment}\n  # 接入组名【上面配置的组名称】注意: 若通过注解配置了这里的配置不生效\n  group: ${spring.application.name}-${application.version:main}\n  # 接入组 token 【上面配置的token信息】\n  token: SJ_Wyz3dmsdbDOkDujOTSSoBjGQP1BMsVnj\n  # 客户端绑定IP，必须服务器可以访问到；默认自动推断，在服务器无法调度客户端时需要手动配置\n#   host: 127.0.0.1\n  # 客户端通讯端口，默认 17889\n  port: 17889\n\n  # 实例标签带版本号，控制台可按版本筛选\n  labels:\n    version: ${application.version:main}', 'e7531d54aab1e483cdefa891148db82b', '2026-09-02 23:36:14', '2026-10-21 14:19:48', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
